import { PrismaClient } from "@prisma/client";

/**
 * Single PrismaClient for the process.
 *
 * Production and CI use the standard client (native query engine).
 * PRISMA_DRIVER_ADAPTER=pg selects Prisma's pure-JS PostgreSQL driver adapter
 * instead. It only works with a client generated by
 * scripts/generate-engine-free-client.sh and exists so the database integration
 * tests can run where the native engine cannot be downloaded. It is never set in
 * the deployment manifests.
 */
async function createClient(): Promise<PrismaClient> {
  if (process.env.PRISMA_DRIVER_ADAPTER === "pg") {
    const { PrismaPg } = await import("@prisma/adapter-pg");
    const adapter = new PrismaPg({ connectionString: process.env.DATABASE_URL });
    return new PrismaClient({ adapter } as never);
  }
  return new PrismaClient();
}

export const prisma = await createClient();

export const connectDatabase = async (): Promise<void> => {
  await prisma.$connect();

  console.log("PostgreSQL connected successfully");
};

export const disconnectDatabase = async (): Promise<void> => {
  await prisma.$disconnect();
};
